SELECT setval(pg_get_serial_sequence('sections', 'id'), GREATEST(COALESCE(MAX(id), 0), 1), MAX(id) IS NOT NULL) FROM sections;
SELECT setval(pg_get_serial_sequence('categories', 'id'), GREATEST(COALESCE(MAX(id), 0), 1), MAX(id) IS NOT NULL) FROM categories;
SELECT setval(pg_get_serial_sequence('letter_sign_pairs', 'id'), GREATEST(COALESCE(MAX(id), 0), 1), MAX(id) IS NOT NULL) FROM letter_sign_pairs;
SELECT setval(pg_get_serial_sequence('roles', 'id'), GREATEST(COALESCE(MAX(id), 0), 1), MAX(id) IS NOT NULL) FROM roles;
SELECT setval(pg_get_serial_sequence('institutions', 'id'), GREATEST(COALESCE(MAX(id), 0), 1), MAX(id) IS NOT NULL) FROM institutions;
